                // Update diagonal counts (top-left to bottom-right)
                diagCounts[i - j + cols] = diagCounts[i - j + cols] + 1;
                // Update anti-diagonal counts (top-right to bottom-left)
                antiDiagCounts[i + j] = antiDiagCounts[i + j] + 1;

                // Update the maximum length found
                maxLength = Math.max(maxLength, rowCounts[i]);
                maxLength = Math.max(maxLength, colCounts[j]);
                maxLength = Math.max(maxLength, diagCounts[i - j + cols]);
                maxLength = Math.max(maxLength, antiDiagCounts[i + j]);
            } else {
